            if event['symbol'] == result['symbol']:
                validated_data.append({
                    'symbol': event['symbol'],
                    'event_type': event['event_type'],
                    'growth_yoy_revenue': result['growth_yoy_revenue_pct'],
                    'growth_qoq_revenue': result['growth_qoq_revenue_pct']
                })
    return validated_data

